  const db = v => 10 * Math.log10(v + 1e-300), f = Array.from(R.D.f), top = Math.max(...Array.from(R.D.s1).filter((v, k) => f[k] >= O.fmin && f[k] <= O.fmax)), rel = a => Array.from(a, v => db(v / top));
