    <label class="f">Carriles cargados<select id="hlL">${[1, 2, 3, 4].map(n => `<option value="${n}" ${n === H.lanes ? 'selected' : ''}>${n} · presencia múltiple ${fmt(OPC.HL93.m[n - 1], 2)}</option>`).join('')}</select></label>
