  const C = $('#canvas'), save = (re = true) => { pgSave(); if (re) vInspMTC(); };
  C.querySelectorAll('[data-r]').forEach(i => i.onchange = () => { r[i.dataset.r] = i.dataset.r === 'cal' ? (i.value === '' ? '' : +i.value) : i.value; save(i.dataset.r !== 'obs'); });
