    if (!C.iaM[kF]) C.iaM[kF] = (await fqRun(ctx, { kind: 'trainM', camp: C.camp, sel: { f: Q.sel.f, s: [], sens: Q.sel.sens }, sf, ss }, m => prog({ ...m, stage: 'IA solo frecuencias · ' + m.stage }))).ia;
