  const allPts = W.flatMap((w, i) => w.peaks.map(p => ({ x: i + 1, y: p.f, c: '#b9c0c6' }))), md = Rc.modes.slice(0, 8);
  const scat = pgPlot({ series: [{ x: [0, W.length + 1], y: [R.D.f[1], R.D.f[1]], c: 'transparent' }], pts: allPts.concat(md.flatMap((c, m) => c.pts.map(q => ({ x: q.wi + 1, y: q.f, c: cols[m % 8] })))), xlab: 'Registro', ylab: 'Frecuencia (Hz)', h: 260, xr: [.5, W.length + .5], yr: [PG.oma.fmin, Math.min(PG.oma.fmax, Math.max(...allPts.map(p => p.y)) * 1.05)], xfmt: v => String(Math.round(v)) });
